// Advanced ML Analytics Master Controller
const timestamp = new Date().toISOString();
const component = msg.req ? msg.req.params.component : 'all';
const triggerType = msg.topic || 'manual';

// Initialize processing context
const mlContext = {
    session_id: 'ml_' + Date.now(),
    timestamp: timestamp,
    trigger_type: triggerType,
    component: component,
    processing_queue: [],
    status: 'initializing'
};

// Define ML components processing order
const mlComponents = [
    {
        name: 'form_scores',
        priority: 1,
        dependencies: ['cards_data', 'results_data'],
        estimated_time: 60,
        parallel: true
    },
    {
        name: 'power_ratings', 
        priority: 1,
        dependencies: ['cards_data', 'track_data'],
        estimated_time: 90,
        parallel: true
    },
    {
        name: 'speed_ratings',
        priority: 2, 
        dependencies: ['results_data', 'timing_data'],
        estimated_time: 40,
        parallel: true
    },
    {
        name: 'pace_analysis',
        priority: 2,
        dependencies: ['sectional_data', 'race_shape'],
        estimated_time: 30,
        parallel: true
    },
    {
        name: 'z_scores',
        priority: 3,
        dependencies: ['form_scores', 'power_ratings', 'speed_ratings'],
        estimated_time: 25,
        parallel: false
    },
    {
        name: 'monte_carlo',
        priority: 4,
        dependencies: ['all_analytics_complete'],
        estimated_time: 300,
        parallel: false
    }
];

// Data readiness check
const dataReadiness = {
    cards_data: true,  // Simulate - in real implementation check actual data
    results_data: true,
    track_data: true,
    timing_data: true,
    sectional_data: true,
    race_shape: true
};

// Filter components based on trigger
let componentsToProcess;
if (component === 'all') {
    componentsToProcess = mlComponents;
} else {
    componentsToProcess = mlComponents.filter(comp => comp.name === component);
}

// Check dependencies and build processing queue
for (const comp of componentsToProcess) {
    const dependenciesMet = comp.dependencies.every(dep => 
        dataReadiness[dep] || dep === 'all_analytics_complete'
    );

    if (dependenciesMet) {
        mlContext.processing_queue.push({
            component: comp.name,
            priority: comp.priority,
            estimated_time: comp.estimated_time,
            parallel: comp.parallel,
            status: 'queued',
            start_time: null,
            end_time: null
        });
    } else {
        node.warn(`Dependencies not met for ${comp.name}: ${comp.dependencies.join(', ')}`);
    }
}

// Sort processing queue by priority
mlContext.processing_queue.sort((a, b) => a.priority - b.priority);

// Calculate total estimated processing time
const totalTime = mlContext.processing_queue.reduce((sum, item) => sum + item.estimated_time, 0);
mlContext.estimated_completion = new Date(Date.now() + totalTime * 1000).toISOString();
mlContext.total_components = mlContext.processing_queue.length;

// Update status
mlContext.status = 'ready_to_process';

// Store context in flow variables
flow.set('mlContext', mlContext);

// Send initial status update
msg.payload = {
    action: 'ml_processing_initialized',
    session_id: mlContext.session_id,
    components_queued: mlContext.total_components,
    estimated_completion: mlContext.estimated_completion,
    processing_queue: mlContext.processing_queue.map(item => ({
        component: item.component,
        priority: item.priority,
        estimated_time: item.estimated_time + 's'
    }))
};

node.status({fill: "blue", shape: "ring", text: `Queued: ${mlContext.total_components} components`});

return msg;

// ML Component Dispatcher - Routes to appropriate subflows
const mlContext = flow.get('mlContext');

if (!mlContext || mlContext.processing_queue.length === 0) {
    node.warn('No ML components in processing queue');
    return null;
}

// Get next component to process
const nextComponent = mlContext.processing_queue.find(comp => comp.status === 'queued');

if (!nextComponent) {
    // All components processed or processing
    msg.payload = {
        action: 'all_components_dispatched',
        session_id: mlContext.session_id,
        status: 'monitoring_progress'
    };
    return msg;
}

// Mark component as processing
nextComponent.status = 'processing';
nextComponent.start_time = new Date().toISOString();

// Update context
flow.set('mlContext', mlContext);

// Prepare message for subflow routing
const componentMsg = {
    payload: {
        component: nextComponent.component,
        session_id: mlContext.session_id,
        priority: nextComponent.priority,
        start_time: nextComponent.start_time,
        database_config: {
            cards_db: 'cards_horse_racing_db',
            results_db: 'results_horse_racing_db', 
            advanced_db: 'advanced_horse_racing_db'
        }
    },
    topic: `ml_${nextComponent.component}`,
    component_name: nextComponent.component
};

node.status({
    fill: "yellow", 
    shape: "ring", 
    text: `Processing: ${nextComponent.component}`
});

// Route to appropriate output based on component
switch(nextComponent.component) {
    case 'form_scores':
        return [componentMsg, null, null, null, null, null];
    case 'power_ratings':
        return [null, componentMsg, null, null, null, null];
    case 'speed_ratings':
        return [null, null, componentMsg, null, null, null];
    case 'pace_analysis':
        return [null, null, null, componentMsg, null, null];
    case 'z_scores':
        return [null, null, null, null, componentMsg, null];
    case 'monte_carlo':
        return [null, null, null, null, null, componentMsg];
    default:
        node.error(`Unknown component: ${nextComponent.component}`);
        return null;
}

// ML Analytics Progress Tracking and Monitoring
const mlContext = flow.get('mlContext') || {};
const timestamp = new Date().toISOString();

// Initialize progress tracking
if (!mlContext.progress) {
    mlContext.progress = {
        total_components: mlContext.total_components || 0,
        completed: 0,
        failed: 0,
        processing: 0,
        start_time: timestamp,
        completion_times: {},
        error_log: []
    };
}

// Update progress based on incoming message
if (msg.payload && msg.payload.action) {
    const action = msg.payload.action;
    const component = msg.payload.component;

    switch(action) {
        case 'component_completed':
            mlContext.progress.completed++;
            mlContext.progress.processing = Math.max(0, mlContext.progress.processing - 1);
            mlContext.progress.completion_times[component] = {
                start: msg.payload.start_time,
                end: timestamp,
                duration: msg.payload.duration || 'unknown'
            };
            break;

        case 'component_failed':
            mlContext.progress.failed++;
            mlContext.progress.processing = Math.max(0, mlContext.progress.processing - 1);
            mlContext.progress.error_log.push({
                component: component,
                error: msg.payload.error,
                timestamp: timestamp
            });
            break;

        case 'component_started':
            mlContext.progress.processing++;
            break;
    }
}

// Calculate overall progress
const totalProcessed = mlContext.progress.completed + mlContext.progress.failed;
const progressPercentage = mlContext.progress.total_components > 0 ? 
    Math.round((totalProcessed / mlContext.progress.total_components) * 100) : 0;

// Determine status
let overallStatus;
if (mlContext.progress.failed > 0) {
    overallStatus = 'warning';
} else if (totalProcessed === mlContext.progress.total_components) {
    overallStatus = 'completed';
} else if (mlContext.progress.processing > 0) {
    overallStatus = 'processing';
} else {
    overallStatus = 'waiting';
}

// Update context
flow.set('mlContext', mlContext);

// Prepare dashboard update
const dashboardUpdate = {
    session_id: mlContext.session_id,
    timestamp: timestamp,
    progress: {
        percentage: progressPercentage,
        completed: mlContext.progress.completed,
        failed: mlContext.progress.failed,
        processing: mlContext.progress.processing,
        total: mlContext.progress.total_components
    },
    status: overallStatus,
    component_status: mlContext.processing_queue ? mlContext.processing_queue.map(comp => ({
        name: comp.component,
        status: comp.status,
        start_time: comp.start_time,
        end_time: comp.end_time,
        estimated_time: comp.estimated_time
    })) : [],
    recent_completions: Object.keys(mlContext.progress.completion_times).slice(-3),
    error_count: mlContext.progress.error_log.length
};

msg.payload = dashboardUpdate;
msg.topic = 'ml_progress_update';

// Update node status
node.status({
    fill: overallStatus === 'completed' ? 'green' : 
          overallStatus === 'warning' ? 'yellow' : 'blue',
    shape: overallStatus === 'processing' ? 'ring' : 'dot',
    text: `${progressPercentage}% (${mlContext.progress.completed}/${mlContext.progress.total_components})`
});

// Check if processing complete
if (overallStatus === 'completed') {
    // Trigger final aggregation
    const completionMsg = {
        payload: {
            action: 'ml_processing_complete',
            session_id: mlContext.session_id,
            total_time: Date.now() - new Date(mlContext.progress.start_time).getTime(),
            components_completed: mlContext.progress.completed,
            components_failed: mlContext.progress.failed,
            completion_times: mlContext.progress.completion_times
        },
        topic: 'ml_processing_complete'
    };

    return [msg, completionMsg];
}

return [msg, null];

// Real-time ML Analytics Dashboard Updates
const dashboardData = msg.payload;

// Format data for dashboard display
const formattedUpdate = {
    timestamp: dashboardData.timestamp,
    ml_analytics: {
        session_id: dashboardData.session_id,
        overall_progress: dashboardData.progress.percentage,
        status: dashboardData.status,
        components: {
            total: dashboardData.progress.total,
            completed: dashboardData.progress.completed,
            processing: dashboardData.progress.processing,
            failed: dashboardData.progress.failed
        },
        current_operations: dashboardData.component_status.filter(comp => comp.status === 'processing').map(comp => ({
            component: comp.name,
            duration: comp.start_time ? Math.floor((Date.now() - new Date(comp.start_time).getTime()) / 1000) : 0
        })),
        recent_completions: dashboardData.recent_completions,
        error_count: dashboardData.error_count,
        next_component: dashboardData.component_status.find(comp => comp.status === 'queued')?.name || null
    }
};

msg.payload = formattedUpdate;
msg.topic = 'dashboard_ml_analytics';

return msg;

// ML Analytics Processing Completion Handler
if (!msg.payload || msg.payload.action !== 'ml_processing_complete') {
    return null;
}

const completionData = msg.payload;
const timestamp = new Date().toISOString();

// Generate completion report
const completionReport = {
    session_id: completionData.session_id,
    completion_timestamp: timestamp,
    processing_summary: {
        total_time_seconds: Math.floor(completionData.total_time / 1000),
        total_time_formatted: formatDuration(completionData.total_time),
        components_completed: completionData.components_completed,
        components_failed: completionData.components_failed,
        success_rate: Math.round((completionData.components_completed / (completionData.components_completed + completionData.components_failed)) * 100)
    },
    component_performance: Object.entries(completionData.completion_times).map(([component, times]) => ({
        component: component,
        duration: times.duration,
        start_time: times.start,
        end_time: times.end
    })),
    api_endpoints_updated: [
        '/ml-analytics/form-scores',
        '/ml-analytics/power-ratings',
        '/ml-analytics/speed-ratings', 
        '/ml-analytics/pace-analysis',
        '/ml-analytics/z-scores',
        '/ml-analytics/monte-carlo',
        '/ml-analytics/complete-analysis'
    ],
    next_scheduled_run: getNextScheduledRun(),
    status: 'completed'
};

// Function to format duration
function formatDuration(milliseconds) {
    const seconds = Math.floor(milliseconds / 1000);
    const minutes = Math.floor(seconds / 60);
    const remainingSeconds = seconds % 60;
    return `${minutes}m ${remainingSeconds}s`;
}

// Function to get next scheduled run
function getNextScheduledRun() {
    const tomorrow = new Date();
    tomorrow.setDate(tomorrow.getDate() + 1);
    tomorrow.setHours(6, 0, 0, 0);
    return tomorrow.toISOString();
}

// Clean up flow variables
flow.set('mlContext', null);

// Send completion notifications
msg.payload = completionReport;
msg.topic = 'ml_processing_completed';

node.status({fill: "green", shape: "dot", text: `Completed: ${completionData.components_completed} components`});

return msg;

// Send completion notifications
const report = msg.payload;

// Email notification (if configured)
const emailNotification = {
    to: process.env.ADMIN_EMAIL || 'admin@horseracingai.com',
    subject: `ML Analytics Processing Complete - Session ${report.session_id}`,
    body: `
Machine Learning Analytics Processing Completed Successfully

Session ID: ${report.session_id}
Completion Time: ${report.completion_timestamp}
Total Processing Time: ${report.processing_summary.total_time_formatted}
Components Completed: ${report.processing_summary.components_completed}
Success Rate: ${report.processing_summary.success_rate}%

API endpoints have been updated with fresh analytics data.
Next scheduled run: ${report.next_scheduled_run}

-- Horse Racing AI System
    `
};

// Slack notification (if configured)
const slackNotification = {
    channel: '#ml-analytics',
    text: `🧠 ML Analytics Complete`,
    attachments: [{
        color: 'good',
        fields: [
            {title: 'Session ID', value: report.session_id, short: true},
            {title: 'Processing Time', value: report.processing_summary.total_time_formatted, short: true},
            {title: 'Components', value: `${report.processing_summary.components_completed} completed`, short: true},
            {title: 'Success Rate', value: `${report.processing_summary.success_rate}%`, short: true}
        ]
    }]
};

msg.email = emailNotification;
msg.slack = slackNotification;
msg.payload = report;

return msg;

// Update API endpoints with fresh ML analytics data
const report = msg.payload;
const timestamp = new Date().toISOString();

// API endpoint update commands
const apiUpdates = [
    {
        endpoint: '/ml-analytics/form-scores',
        status: 'updated',
        last_update: timestamp,
        data_source: 'advanced_horse_racing_db.form_scores'
    },
    {
        endpoint: '/ml-analytics/power-ratings',
        status: 'updated',
        last_update: timestamp,
        data_source: 'advanced_horse_racing_db.power_ratings'
    },
    {
        endpoint: '/ml-analytics/speed-ratings',
        status: 'updated',
        last_update: timestamp,
        data_source: 'advanced_horse_racing_db.speed_ratings'
    },
    {
        endpoint: '/ml-analytics/pace-analysis',
        status: 'updated',
        last_update: timestamp,
        data_source: 'advanced_horse_racing_db.pace_analysis'
    },
    {
        endpoint: '/ml-analytics/z-scores',
        status: 'updated',
        last_update: timestamp,
        data_source: 'advanced_horse_racing_db.z_scores'
    },
    {
        endpoint: '/ml-analytics/monte-carlo',
        status: 'updated',
        last_update: timestamp,
        data_source: 'advanced_horse_racing_db.monte_carlo_simulations'
    }
];

// Store API status in global context
global.set('ml_api_status', {
    last_update: timestamp,
    session_id: report.session_id,
    endpoints: apiUpdates,
    processing_summary: report.processing_summary
});

msg.payload = {
    action: 'api_endpoints_updated',
    timestamp: timestamp,
    endpoints_updated: apiUpdates.length,
    endpoints: apiUpdates
};

return msg;

